	@ParameterizedTest(name = "{0}")
	@MethodSource("lmdbTemplates")
	void combinationsRetainLmdbFieldsAndApplySubmittedSettings(String type) throws Exception {
		CreateTemplateConfig template = CreateServlet.getCreateTemplate(type);
		CreateTemplateConfig baseline = CreateServlet.getCreateTemplate("lmdb");
		CreateTemplateConfig.Field graphJoinOptimization = baseline.getFields()
				.stream()
				.filter(candidate -> candidate.getName().equals("Graph join optimization"))
				.findFirst()
				.orElseThrow();
		assertThat(graphJoinOptimization.getProperty()).isEqualTo("config:sail.graphJoinOptimization");
		assertThat(template.getFields()).extracting(CreateTemplateConfig.Field::getName)
				.containsAll(baseline.getFields().stream().map(CreateTemplateConfig.Field::getName).toList());
		for (CreateTemplateConfig.Field field : baseline.getFields()) {
			if (field.getName().equals("Repository ID") || field.getName().equals("Repository title")) {
				continue;
			}
			CreateTemplateConfig.Field actual = template.getFields()
					.stream()
					.filter(candidate -> candidate.getName().equals(field.getName()))
					.findFirst()
					.orElseThrow();
			assertThat(actual.getProperty()).as(field.getName()).isEqualTo(field.getProperty());
			assertThat(actual.getValues()).as(field.getName()).isEqualTo(field.getValues());
			assertThat(actual.getControl()).as(field.getName()).isEqualTo(field.getControl());
			assertThat(actual.isUnsettable()).as(field.getName()).isEqualTo(field.isUnsettable());
		}

		Map<String, String> values = defaultValues(template);
		values.put("Triple indexes", "spoc,posc");
		values.put("Bulk operation size", "128");
		values.put("Triple DB size", "16777216");
		values.put("Value DB size", "33554432");
		values.put("Query Evaluation Mode", "STRICT");
		values.put("Graph join optimization", "OFF");
		values.put("Sketch estimator enabled", CreateTemplateConfig.UNSET_VALUE);

		LocalRepositoryManager manager = new LocalRepositoryManager(dataDir.toFile());
		try {
			manager.init();
			RepositoryConfig config = createConfig(manager, template, values);
			assertThat(config.getID()).isEqualTo(type);
			assertThat(config.getTitle()).isNotBlank();
			SailImplConfig sailConfig = ((SailRepositoryConfig) config.getRepositoryImplConfig()).getSailImplConfig();
			if (type.contains("shacl")) {
				assertThat(sailConfig).isInstanceOf(ShaclSailConfig.class);
				assertThat(((ShaclSailConfig) sailConfig).isSerializableValidation()).isEqualTo(!type.contains("rdfs"));
			}
			LmdbStoreConfig lmdb = innermostLmdbConfig(config);
			assertThat(lmdb.getTripleIndexes()).isEqualTo("spoc,posc");
			assertThat(lmdb.getBulkOperationSize()).isEqualTo(128);
			assertThat(lmdb.getTripleDBSize()).isEqualTo(16777216L);
			assertThat(lmdb.getValueDBSize()).isEqualTo(33554432L);
			assertThat(lmdb.getGraphJoinOptimization()).isEqualTo(GraphJoinOptimization.OFF);
			assertThat(lmdb.getDefaultQueryEvaluationMode()).contains(QueryEvaluationMode.STRICT);
			assertThat(template.render(values)).doesNotContain("lmdb:sketchEstimatorEnabled");
		} finally {
			manager.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("lmdbTemplates")
	void createdRepositoriesInferValidateSearchAndPersist(String type) throws Exception {
		boolean rdfs = type.contains("rdfs");
		boolean shacl = type.contains("shacl");
		boolean lucene = type.contains("lucene");
		CreateTemplateConfig template = CreateServlet.getCreateTemplate(type);
		LocalRepositoryManager manager = new LocalRepositoryManager(dataDir.toFile());
		try {
			manager.init();
			RepositoryConfig config = createConfig(manager, template, defaultValues(template));
			assertThat(innermostLmdbConfig(config).getGraphJoinOptimization()).isEqualTo(GraphJoinOptimization.AUTO);
			Repository repository = manager.getRepository(type);
			assertThat(repository).isNotNull();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				connection.add(NAME, RDFS.SUBPROPERTYOF, DISPLAY_NAME);
				connection.add(NAME, RDFS.DOMAIN, PERSON_CLASS);
				if (shacl) {
					connection.add(new StringReader(shape(rdfs)), "", RDFFormat.TURTLE, RDF4J.SHACL_SHAPE_GRAPH);
				}
				connection.commit();

				addPerson(connection, PERSON, "albatross", rdfs);
				assertStoredData(connection, rdfs, lucene, "albatross");
				if (shacl) {
					assertInvalidCommitIsRejected(connection, rdfs, lucene);
				}

				connection.begin();
				if (!rdfs) {
					connection.add(ROLLED_BACK_PERSON, RDF.TYPE, PERSON_CLASS);
				}
				connection.add(ROLLED_BACK_PERSON, NAME, literal("rollbacktoken"));
				connection.rollback();
				assertThat(connection.hasStatement(ROLLED_BACK_PERSON, null, null, true)).isFalse();
				if (lucene) {
					assertThat(search(connection, "rollbacktoken", null)).isEmpty();
					assertThat(search(connection, "shapesecrettoken", null)).isEmpty();
				}

				connection.begin();
				connection.remove(PERSON, null, null);
				connection.commit();
				assertThat(connection.hasStatement(PERSON, NAME, null, true)).isFalse();
				assertThat(connection.hasStatement(PERSON, DISPLAY_NAME, null, true)).isFalse();
				if (lucene) {
					assertThat(search(connection, "albatross", null)).isEmpty();
				}
				addPerson(connection, PERSON, "seabird", rdfs);
			}
		} finally {
			manager.shutDown();
		}

		LocalRepositoryManager reopened = new LocalRepositoryManager(dataDir.toFile());
		try {
			reopened.init();
			try (RepositoryConnection connection = reopened.getRepository(type).getConnection()) {
				assertStoredData(connection, rdfs, lucene, "seabird");
				if (shacl) {
					assertInvalidCommitIsRejected(connection, rdfs, lucene);
				}
			}
		} finally {
			reopened.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("shaclTemplates")
	void snapshotTransactionsValidateWithMultipleOpenConnections(String type) throws Exception {
		boolean rdfs = type.contains("rdfs");
		boolean lucene = type.contains("lucene");
		CreateTemplateConfig template = CreateServlet.getCreateTemplate(type);
		LocalRepositoryManager manager = new LocalRepositoryManager(dataDir.toFile());
		try {
			manager.init();
			createConfig(manager, template, defaultValues(template));
			Repository repository = manager.getRepository(type);
			// A second open connection prevents SHACL's single-connection fast path from skipping serializable
			// validation.
			try (RepositoryConnection connection = repository.getConnection();
					RepositoryConnection observer = repository.getConnection()) {
				connection.setIsolationLevel(IsolationLevels.SNAPSHOT);
				connection.begin();
				connection.add(NAME, RDFS.SUBPROPERTYOF, DISPLAY_NAME);
				connection.add(NAME, RDFS.DOMAIN, PERSON_CLASS);
				connection.add(new StringReader(shape(rdfs)), "", RDFFormat.TURTLE, RDF4J.SHACL_SHAPE_GRAPH);
				connection.commit();

				addPerson(connection, PERSON, "albatross", rdfs);
				assertStoredData(observer, rdfs, lucene, "albatross");
				assertInvalidCommitIsRejected(connection, rdfs, lucene);
				assertStoredData(observer, rdfs, lucene, "albatross");
			}
		} finally {
			manager.shutDown();
		}
	}

	private static void addPerson(RepositoryConnection connection, IRI person, String name, boolean rdfs) {
		connection.begin();
		if (!rdfs) {
			connection.add(person, RDF.TYPE, PERSON_CLASS);
		}
		connection.add(person, NAME, literal(name));
		connection.commit();
	}

	private static void assertStoredData(RepositoryConnection connection, boolean rdfs, boolean lucene, String name) {
		assertThat(connection.hasStatement(PERSON, NAME, literal(name), false)).isTrue();
		assertThat(connection.hasStatement(PERSON, DISPLAY_NAME, literal(name), false)).isFalse();
		assertThat(connection.hasStatement(PERSON, DISPLAY_NAME, literal(name), true)).isEqualTo(rdfs);
		assertThat(connection.hasStatement(PERSON, RDF.TYPE, PERSON_CLASS, true)).isTrue();

		TupleQuery query = connection.prepareTupleQuery("SELECT ?name WHERE { <urn:workbench:person>"
				+ " <urn:workbench:displayName> ?name }");
		query.setIncludeInferred(false);
		assertThat(column(query, "name")).isEmpty();
		query.setIncludeInferred(true);
		assertThat(column(query, "name")).containsExactlyElementsOf(rdfs ? List.of(name) : List.of());

		if (lucene) {
			assertThat(search(connection, name, NAME)).containsExactly(PERSON.stringValue());
			assertThat(search(connection, name, DISPLAY_NAME))
					.containsExactlyElementsOf(rdfs ? List.of(PERSON.stringValue()) : List.of());
		}
	}

	private static void assertInvalidCommitIsRejected(RepositoryConnection connection, boolean rdfs, boolean lucene) {
		connection.begin();
		if (!rdfs) {
			connection.add(INVALID_PERSON, RDF.TYPE, PERSON_CLASS);
		}
		// With RDFS, both the target class and the constrained property are inferred from name.
		connection.add(INVALID_PERSON, NAME, literal(42));
		connection.add(INVALID_PERSON, RDFS.LABEL, literal("rejectedtoken"));
		assertThatThrownBy(connection::commit).isInstanceOf(RepositoryException.class)
				.hasCauseInstanceOf(ShaclSailValidationException.class);
		if (connection.isActive()) {
			connection.rollback();
		}
		assertThat(connection.hasStatement(INVALID_PERSON, null, null, true)).isFalse();
		if (lucene) {
			assertThat(search(connection, "rejectedtoken", null)).isEmpty();
		}
	}

	private static List<String> search(RepositoryConnection connection, String text, IRI property) {
		TupleQuery query = connection.prepareTupleQuery("PREFIX search: <http://www.openrdf.org/contrib/lucenesail#> "
				+ "SELECT ?result WHERE { ?result search:matches [ search:query ?text"
				+ (property == null ? "" : " ; search:property ?property") + " ] }");
		query.setBinding("text", literal(text));
		if (property != null) {
			query.setBinding("property", property);
		}
		return column(query, "result");
	}

	private static List<String> column(TupleQuery query, String variable) {
		List<String> values = new ArrayList<>();
		try (TupleQueryResult results = query.evaluate()) {
			while (results.hasNext()) {
				values.add(results.next().getValue(variable).stringValue());
			}
		}
		return values;
	}

	private static String shape(boolean rdfs) {
		return """
				@prefix sh: <http://www.w3.org/ns/shacl#> .
				@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
				<urn:workbench:PersonShape> a sh:NodeShape ;
				    sh:targetClass <urn:workbench:Person> ;
				    sh:property [
				        sh:path <%s> ;
				        sh:minCount 1 ;
				        sh:datatype xsd:string ;
				        sh:message "shapesecrettoken"
				    ] .
				""".formatted(rdfs ? DISPLAY_NAME : NAME);
	}

	private static RepositoryConfig createConfig(LocalRepositoryManager manager, CreateTemplateConfig template,
			Map<String, String> values) throws IOException {
		CreateServlet servlet = new CreateServlet();
		servlet.setRepositoryManager(manager);
		return servlet.updateRepositoryConfig(template.render(values));
	}

	private static LmdbStoreConfig innermostLmdbConfig(RepositoryConfig config) {
		SailImplConfig sailConfig = ((SailRepositoryConfig) config.getRepositoryImplConfig()).getSailImplConfig();
		while (sailConfig instanceof DelegatingSailImplConfig delegating) {
			sailConfig = delegating.getDelegate();
		}
		assertThat(sailConfig).isInstanceOf(LmdbStoreConfig.class);
		return (LmdbStoreConfig) sailConfig;
	}

	private static Map<String, String> defaultValues(CreateTemplateConfig template) {
		Map<String, String> values = new LinkedHashMap<>();
		for (CreateTemplateConfig.Field field : template.getFields()) {
			values.put(field.getName(), field.getDefaultValue());
		}
		return values;
	}

	private static Stream<String> lmdbTemplates() {
		return LMDB_TEMPLATES.stream();
	}

	private static Stream<String> shaclTemplates() {
		return lmdbTemplates().filter(type -> type.contains("shacl"));
	}
